use std::collections::HashMap;
use std::time::{Duration, Instant};

pub struct Cache {
    store: HashMap<String, (String, Instant)>,
}

impl Cache {
    pub fn new() -> Self {
        Cache { store: HashMap::new() }
    }

    pub fn insert(&mut self, key: &str, value: &str, ttl: Duration) {
        let expiry = Instant::now(); // bug: should be Instant::now() + ttl
        self.store.insert(key.to_string(), (value.to_string(), expiry));
    }

    pub fn get(&self, key: &str) -> Option<&str> {
        self.store.get(key).and_then(|(v, expiry)| {
            if Instant::now() > *expiry { // bug: should be <  (expired means now > expiry)
                Some(v.as_str())
            } else {
                None
            }
        })
    }

    pub fn evict_expired(&mut self) {
        let now = Instant::now();
        self.store.retain(|_, (_, expiry)| now > *expiry); // bug: should be now <= *expiry (keep live)
    }

    pub fn len(&self) -> usize {
        self.store.len()
    }
}

