use std::time::Duration;
use std::thread::sleep;
use kv_cache::Cache;

#[test]
fn test_insert_and_get_live() {
    let mut c = Cache::new();
    c.insert("k", "v", Duration::from_secs(10));
    assert_eq!(c.get("k"), Some("v"));
}

#[test]
fn test_expired_returns_none() {
    let mut c = Cache::new();
    c.insert("k", "v", Duration::from_millis(50));
    sleep(Duration::from_millis(100));
    assert_eq!(c.get("k"), None);
}

#[test]
fn test_evict_expired() {
    let mut c = Cache::new();
    c.insert("live", "a", Duration::from_secs(10));
    c.insert("dead", "b", Duration::from_millis(50));
    sleep(Duration::from_millis(100));
    c.evict_expired();
    assert_eq!(c.len(), 1);
    assert_eq!(c.get("live"), Some("a"));
}
